rmsnorm_kernel(const scalar_t* __restrict__ input, const scalar_t* __restrict__ weight, scalar_t* __restrict__ out, float eps, int rows, int cols) {
  for (int row = blockIdx.x; row < rows; row += gridDim.x) {
     float sum_sq = 0;
     for (int col = threadIdx.x; col < cols; col += blockDim.x) {
        float x = static_cast<float>(input[row*cols+col]);
        sum_sq += x*x;
     }
     // block reduce sum_sq
     __shared__ float shared[...] or warp reduce.
     sum_sq = blockReduceSum(sum_sq);
     float inv_rms = rsqrtf(sum_sq/cols + eps);
     __shared__ float s_inv_rms;
     if (threadIdx.x==0) s_inv_rms = inv_rms;
     __syncthreads();
     for col .. {
        float x = static_cast<float>(input[row*cols+col]);
        float w = static_cast<float>(weight[col]);
        out[row*cols+col] = static_cast<scalar_t>(x * w * s_inv_rms);
     }
  }
}

