```cuda
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>
#include <ATen/Dispatch.h>
#include <cuda_runtime.h>

static __device__ __forceinline__ float warpReduceSum(float v) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffff, v, offset);
    }
    return v;
}

static __device__ __forceinline__ float blockReduceSum(float v) {
    __shared__ float s[32];
    int lane = threadIdx.x & 31;
    int wid  = threadIdx.x >> 5;
    v = warpReduceSum(v);
    if (lane == 0) s[wid] = v;
    __syncthreads();
    v = (threadIdx.x < (blockDim.x >> 5)) ? s[lane] : 0.0f;
    if (wid == 0) v = warpReduceSum(v);
    return v;
}

template <typename scalar_t>
__global__ void rmsnorm_forward_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int rows, int cols, float eps)
{
    const float inv_cols = 1.0f / static_cast<float>(cols);
    for (int row = blockIdx.x; row < rows; row += gridDim.x) {
        const scalar_t* row_in = input + static_cast<int64_t>(row) * cols;
        float local_sq = 0.0f;
        for (int col = threadIdx.x; col < cols; col += blockDim.x) {
            float x = static_cast<float>(row_in[col]);
            local_sq += x * x;
        }
        float sum_sq = blockReduceSum(local_sq);
        float inv_rms = rsqrtf(sum_sq * inv_cols + eps);
        scalar_t* row_out = output + static_cast<int64_t>(row) * cols;
        for (int col = threadIdx.x; col < cols; col += blockDim.x) {
            float x = static_cast<float>(row_in[col]);
            float w = static_cast<float>(weight[col]);
            row_out[col] = static_cast<scalar_t>(x * w * inv_rms);
        }
    }
}

template <typename scalar_t>
__global__ void fused_add_rmsnorm_kernel(
    scalar_t* __restrict__ input,     // becomes normalized output
    scalar_t* __restrict__ residual,  // residual += input
    const scalar_t* __restrict__ weight,
    int rows, int cols, float eps)
{
    const float inv_cols = 1.0f / static_cast<float>(cols);
    for (int row = blockIdx.x; row < rows; row += gridDim.x) {
        scalar_t* row_in = input + static_cast<int64_t>(row) * cols;
        scalar_t* row_res = residual + static_cast<int64_t>(row) * cols;
        float local_sq = 0.0f;
        for (int col = threadIdx.x; col < cols; col += blockDim.x) {
            float v = static_cast<float>(row_res[col]) + static_cast<float>(row_in[col]);
            row_res[col] = static_cast<scalar_t>(v);
            local_sq += v * v;
        }
        float sum_sq = blockReduceSum(local_sq);
        float inv_rms = rsqrtf(sum_sq * inv_cols + eps);
        for (int col = threadIdx.x; col < cols; col += blockDim.x) {
            float v = static_cast<float>(row_res[col]);
            float w = static_cast<float>(weight[col]);
            row_in[col] = static_cast<scalar_t>(v * w * inv_rms);
        }
    }
}

template <typename scalar_t>
__global__ void apply_rope_single_kernel(
    scalar_t* __restrict__ tensor,
    int size0, int size1, int nheads, int head_dim,
    const float* __restrict__ cos,
    const float* __restrict__ sin)
{
    const int half = head_dim / 2;
    const int total = size0 * size1 * nheads;
    for (int idx = blockIdx.x; idx < total; idx += gridDim.x) {
        int d = threadIdx.x;
        if (d >= half) continue;
        int head = idx % nheads;
        int token = (idx / nheads) % size1;
        scalar_t* ptr = tensor + static_cast<int64_t>(idx) * head_dim;
        float c = cos[token * half + d];
        float s = sin[token * half + d];
        float e = static_cast<float>(ptr[d]);
        float o = static_cast<float>(ptr[d + half]);
        float ne = e * c - o * s;
        float no = e * s + o * c;
        ptr[d]       = static_cast<scalar_t>(ne);
        ptr[d + half]= static_cast<scalar_t>(no);
    }
}

template <typename scalar_t>
__global__ void silu_and_mul_kernel(
    const scalar_t* __restrict__ gate_up,
    scalar_t* __restrict__ out,
    int rows, int cols)
{
    for (int row = blockIdx.x; row < rows; row += gridDim.x) {
        const scalar_t* row_in = gate_up + static_cast<int64_t>(row) * 2 * cols;
        scalar_t* row_out = out + static_cast<int64_t>(row) * cols;
        for (int col = threadIdx.x; col < cols; col += blockDim.x) {
            float g = static_cast<float>(row_in[col]);
            float u = static_cast<float>(row_in[col + cols]);
            float v = g * (1.0f / (1.0f + expf(-g))) * u;
            row_out[col] = static_cast<scalar_t>(v);
        }
    }
}

torch::Tensor rmsnorm(torch::Tensor input, torch::Tensor weight, float eps) {
    TORCH_CHECK(input.is_cuda(), "rmsnorm input must be CUDA");
    TORCH_CHECK(input.is_contiguous(), "rmsnorm input must be contiguous");
    TORCH_CHECK(input.dim() == 2, "rmsnorm input must be 2D");
    TORCH_CHECK(weight.dim() == 1 && weight.size(0) == input.size(1),
                "rmsnorm weight shape mismatch");
    auto output = torch::empty_like(input);
    int rows = static_cast<int>(input.size(0));
    int cols = static_cast<int>(input.size(1));
    const int threads = 256;
    const int blocks = std::min(rows, 65536);
    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        input.scalar_type(), "rmsnorm", [&] {
        rmsnorm_forward_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            rows, cols, eps);
    });
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}

void fused_add_rmsnorm_(torch::Tensor input, torch::Tensor residual,
                        torch::Tensor weight, float eps) {
    TORCH_CHECK(input.is_cuda(), "fused_add_rmsnorm_ input must be CUDA");
    TORCH_CHECK(input.is_contiguous(), "fused_add_rmsnorm_ input must be contiguous");
    TORCH_CHECK(residual.is_contiguous(), "fused_add_rmsnorm_ residual must be contiguous");
    TORCH_CHECK(input.sizes() == residual.sizes(),
                "fused_add_rmsnorm_ shape mismatch");
    TORCH_CHECK(weight.dim() == 1 && weight.size(0) == input.size(1),
                "fused_add_rmsnorm_ weight shape mismatch");
    int rows = static_cast<int>(input.size(0));
    int cols = static_cast<int>(input.size(1));
    const int threads = 256;
    const int blocks = std::min(rows, 65536);
    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        input.scalar_type(), "fused_add_rmsnorm_", [&] {
        fused_add_rmsnorm_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            residual.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            rows, cols, eps);
    });
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

void apply_rope_(torch::Tensor q, torch::Tensor k,
                 torch::Tensor cos, torch::Tensor sin) {
    TORCH_CHECK(q.is_cuda(), "apply_rope_ q must be CUDA");
    TORCH_CHECK(q.is_contiguous(), "apply_rope_ q must be contiguous");
    TORCH_CHECK(k.is_contiguous(), "apply_rope_ k must be contiguous");
    TORCH_CHECK(cos.is_contiguous() && sin.is_contiguous(),
                "apply_rope_ cos/sin must be contiguous");
    TORCH_CHECK(q.dim() == 4 && k.dim() == 4, "q/k must be 4D");
    TORCH_CHECK(q.size(3) == k.size(3) && q.size(3) % 2 == 0,
                "head_dim mismatch or odd");
    TORCH_CHECK(cos.size(1) == q.size(3) / 2, "cos/sin half dimension mismatch");
    int q_total = static_cast<int>(q.size(0) * q.size(1) * q.size(2));
    int k_total = static_cast<int>(k.size(0) * k.size(1) * k.size(2));
    int half = static_cast<int>(q.size(3) / 2);
    int threads = 32;
    while (threads < half) threads <<= 1;
    threads = std::min(threads, 1024);
    int q_blocks = std::min(q_total, 65536);
    int k_blocks = std::min(k_total, 65536);
    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        q.scalar_type(), "apply_rope_", [&] {
        apply_rope_single_kernel<scalar_t><<<q_blocks, threads>>>(
            q.data_ptr<scalar_t>(),
            static_cast<int>(q.size(0)), static_cast<int>(q.size(1)),
            static_cast<int>(q.size(2)), static_cast<int>(q.size(3)),
            cos.data_ptr<float>(), sin.data_ptr<float>());
        C10_CUDA_KERNEL_LAUNCH_CHECK();
        apply_rope_single_kernel<scalar_t><<<k_blocks, threads>>>(
            k.data_ptr<scalar_t>(),
            static_cast<int>(k.size(0)), static_cast<int>(k.size(1)),
            static_cast<int>(k.size(2)), static_cast<int>(k.size(3)),
            cos.data_ptr<float>(), sin.data_ptr<float>());
    });
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

torch::Tensor silu_and_mul(torch::Tensor gate_up, c10::optional<torch::Tensor> out_) {
    TORCH_CHECK(gate_up.is_cuda(), "silu_and_mul gate_up must be CUDA");
    TORCH_CHECK(gate_up.is_contiguous(), "silu_and_mul gate_up must be contiguous");
    TORCH_CHECK(gate_up.dim() == 2, "silu_and_mul gate_up must be 2D");
    TORCH_CHECK(gate_up.size(1) % 2 == 0, "silu_and_mul gate_up last dim must be even");
    int rows = static_cast<int>(gate_up.size(0));
    int cols = static_cast<int>(gate_up.size(1) / 2);
    torch::Tensor out;
    if (out_.has_value()) {
        out = out_.value();
        TORCH_CHECK(out.is_contiguous(), "silu_and_mul out must be contiguous");
        TORCH_CHECK(out.sizes() == torch::IntArrayRef({rows, cols}),
                    "silu_and_mul out shape mismatch");
    } else {
        out = torch::empty({rows, cols}, gate_up.options());
    }
    const int threads = 256;
    const int blocks = std::min(rows, 65536);
    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        gate_up.scalar_type(), "silu_and_mul", [&] {
        silu_and_mul_kernel<scalar_t><<<blocks, threads>>>(
            gate_up.data_ptr<scalar_t>(),
            out.data_ptr<scalar_t>(),
            rows, cols);
    });
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
```

