torch::Tensor rmsnorm(torch::Tensor input, torch::Tensor weight, float eps);
void fused_add_rmsnorm_(torch::Tensor input, torch::Tensor residual,
                        torch::Tensor weight, float eps);
void apply_rope_(torch::Tensor q, torch::Tensor k,
                 torch::Tensor cos, torch::Tensor sin);
torch::Tensor silu_and_mul(torch::Tensor gate_up,
                           c10::optional<torch::Tensor> out = c10::nullopt);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("rmsnorm", &rmsnorm, "rmsnorm");
    m.def("fused_add_rmsnorm_", &fused_add_rmsnorm_, "fused_add_rmsnorm_");
    m.def("apply_rope_", &apply_rope_, "apply_rope_");
    m.def("silu_and_mul", &silu_and_mul, "silu_and_mul");
}
```

