#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>
#include <ATen/Dispatch.h>
#include <cuda_runtime.h>

static __device__ __forceinline__ float warpReduceSum(float v) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffff, v, offset);
    }
    return v;
}

static __device__ __forceinline__ float blockReduceSum(float v) {
    __shared__ float s[32];
    int lane = threadIdx.x & 31;
    int wid  = threadIdx.x >> 5;
    v = warpReduceSum(v);
    if (lane == 0) s[wid] = v;
    __syncthreads();
    v = (threadIdx.x < (blockDim.x >> 5)) ? s[lane] : 0.0f;
    if (wid == 0) v = warpReduceSum(v);
    return v;
}

template <typename scalar_t>
__global__ void rmsnorm_forward_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int rows, int cols, float eps)
{
    const float inv_cols = 1.0f / static_cast<float>(cols);
    for (int row = blockIdx.x; row < rows; row += gridDim.x) {
        const scalar_t* row_in = input + static_cast<int64_t>(row) * cols;
        float local_sq = 0.0f;
        for (int col = threadIdx.x; col < cols; col += blockDim.x) {
            float x = static_cast<float>(row_in[col]);
            local_sq += x * x;
        }
        float sum_sq = blockReduceSum(local_sq);
        float inv_rms = rsqrtf(sum_sq * inv_cols + eps);
        scalar_t* row_out = output + static_cast<int64_t>(row) * cols;
        for (int col = threadIdx.x; col < cols; col += blockDim.x) {
            float x = static_cast<float>(row_in[col]);
            float w = static_cast<float>(weight[col]);
            row_out[col] = static_cast<scalar_t>(x * w * inv_rms);
        }
    }
}

template <typename scalar_t>
__global__ void fused_add_rmsnorm_kernel(
    scalar_t* __restrict__ input,     // becomes normalized output
    scalar_t* __restrict__ residual,  // residual += input
    const scalar_t* __restrict__ weight,
    int rows, int cols, float eps)
{
    const float inv_cols = 1.0f / static_cast<float>(cols);
    for (int row = blockIdx.x; row < rows; row += gridDim.x) {
        scalar_t* row_in = input + static_cast<int64_t>(row) * cols;
        scalar_t* row_res = residual + static_cast<int64_t>(row) * cols;
        float local_sq = 0.0f;
        for (int col = threadIdx.x; col < cols; col += blockDim.x) {
            float v = static_cast<float>(row_res[col]) + static_cast<float>(row_in[col]);
            row_res[col] = static_cast<scalar_t>(v);
            local_sq += v * v;
        }
        float sum_sq = blockReduceSum(local_sq);
        float inv_rms = rsqrtf(sum_sq * inv_cols + eps);
        for (int col = threadIdx.x; col < cols; col += blockDim.x) {
            float v = static_cast<float>(row_res[col]);
            float w = static_cast<float>(weight[col]);
            row_in[col] = static_cast<scalar_t>(v * w * inv_rms);
        }
    }
}

template <typename scalar_t>
__global__ void apply_rope_single_kernel(
    scalar_t* __restrict__ tensor,
    int size0, int size1, int nheads, int head_dim,
    const float* __restrict__ cos,
    const float* __restrict__ sin)
{
