        float c = cos[token * half + d];
        float s = sin[token * half + d];
        float e = static_cast<float>(ptr[d]);
        float o = static_cast<float>(ptr[d + half]);
        float ne = e * c - o * s;
        float no = e * s + o * c;
        ptr[d]       = static_cast<scalar_t>(ne);
        ptr[d + half]= static_cast<scalar_t>(no);
    }
}

